#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int t = r() % 3 + 1; printf("%d\n", t); while (t--) { int n = r() % 9 + 2; int a = r() % n + 1, b = r() % n + 1; while (b == a) b = r() % n + 1; printf("%d %d %d %d %d\n", n, a, b, int(r() % (n - 1) + 1), int(r() % (n - 1) + 1)); std::vector<int> lab(n); std::iota(lab.begin(), lab.end(), 1); std::shuffle(lab.begin(), lab.end(), r); for (int i = 1; i < n; i++) printf("%d %d\n", lab[r() % i], lab[i]); } }
